r1t:"① まずは駒を置く",
r1c:"空いている点を押して駒を置きます。黒と白が交代に置いていき、全部置き終わるまで続きます。黒が先手です。",
r1c2:"操作：白い矢印が動く先の、空いている点を押すだけです。",
r2t:"② 3つ並べて「ミル」",
r2c:"線の上で自分の駒が3つ並ぶと「ミル」になり、相手の駒を1つ取れます。",
r2c2:"操作：3つ並べたあと、取りたい相手の駒を押します。",
r2c3:"ミルの中にある駒は取れません。ただし相手の駒が全部ミルの中なら、その中から取れます。",
r3t:"③ 置き終わったら動かす",
r3c:"全部置き終わったら、駒を線でつながった隣の空き点へ動かします。動かせる駒には、背景に合った目立つ色の輪がつきます。駒を押すと、行ける点が大きく光ります。",
r3c2:"操作：動かしたい駒を押す → 光った隣の点を押す。",
r4t:"④ 3個になったら飛べる",
r4c:"自分の駒が3個だけになったら、線がつながっていなくても、どの空き点へでも飛べます。",
r4c2:"操作：自分の駒を押す → 飛びたい空き点を押す。",
r5t:"⑤ 勝ち方",
r5c:"相手の駒を2個まで減らすか、相手を動けなくしたら勝ちです。",
r6t:"⑥ 12人モラバラバ",
