r1t:"① Place your pieces first",
r1c:"Tap an empty point to place a piece. Black and White take turns placing until all pieces are on the board. Black moves first.",
r1c2:"How to play: just tap the empty point where the white arrow is heading.",
r2t:"② Line up three: a mill",
r2c:"When three of your pieces line up on a line, that is a mill, and you may take one of your opponent's pieces.",
r2c2:"How to play: after forming a mill, tap the opponent's piece you want to take.",
r2c3:"A piece inside a mill cannot be taken, unless all of your opponent's pieces are in mills; then you may take one from a mill.",
r3t:"③ Then move your pieces",
r3c:"Once all pieces are placed, slide a piece along a line to a neighbouring empty point. Pieces that can move get a ring in a colour that stands out against the background. Tap a piece and its destinations light up.",
r3c2:"How to play: tap the piece you want to move, then tap a lit neighbouring point.",
r4t:"④ Down to three? You can fly",
r4c:"When you have only three pieces left, you may fly to any empty point, even if no line connects them.",
r4c2:"How to play: tap your piece, then tap the empty point you want to fly to.",
r5t:"⑤ How to win",
r5c:"You win by reducing your opponent to two pieces, or by leaving them with no legal move.",
r6t:"⑥ Morabaraba (12 pieces)",
r6c:"Each player has 12 pieces and four diagonal lines are added. You can move diagonally, and three in a row on a diagonal also forms a mill.",
r6c2:"How to play: diagonal moves work the same way — tap the piece, then the destination point.",
r6c3:"If the board fills up completely during the placing phase, the player to move cannot move and loses.",
r7t:"7. Draws",
r7c:"The game is drawn automatically in any of the cases below. There is no button to offer a draw.",
r7c2:"· The same board position with the same player to move occurs three times",
r7c3:"· 50 moves (both players combined) pass without a mill",
r7c4:"· 12-piece version only: while a player has three pieces, 10 moves (combined) pass with nobody capturing",
r8t:"8. Details",
r8c:"Even if one move forms two mills at once, you still take only one piece.",
r8c2:"9-piece version: you may break a mill and close it again on your very next move; each time you close it, you take a piece.",
r8c3:"12-piece version: a mill you broke cannot be remade on your next move; wait one move. Moves that do not form a mill are fine.",
r8c4:"Online games have three paces: Normal is 30 seconds per move, Slow is 2 minutes, and Letter is 24 hours. In Slow and Letter games, a move is played automatically when the time runs out.",
