myInqPrep:"连接成功后，可在此查看自己发送的内容和回复。",
r1t:"① 先放置棋子",
r1c:"点击空点放置棋子。黑白双方轮流放置，直到全部放完。黑方先行。",
r1c2:"操作：只需点击白色箭头所指的空点。",
r2t:"② 三子连线成「磨坊」",
r2c:"自己的3枚棋子在一条线上连成一线即成「磨坊」，可以取走对方1枚棋子。",
r2c2:"操作：连成磨坊后，点击想要取走的对方棋子。",
r2c3:"磨坊内的棋子不能被取走；但如果对方所有棋子都在磨坊内，则可以从中取走。",
r3t:"③ 放完后移动棋子",
r3c:"全部放完后，沿线把棋子移到相邻的空点。可移动的棋子会带上与背景相衬的醒目颜色的圆环；点击棋子后，可去的点会明显发亮。",
r3c2:"操作：点击想移动的棋子 → 再点击发亮的相邻点。",
r4t:"④ 只剩3枚时可以飞",
r4c:"当自己的棋子只剩3枚时，即使没有连线，也可以飞到任意空点。",
r4c2:"操作：点击自己的棋子 → 再点击想飞往的空点。",
r5t:"⑤ 获胜方法",
r5c:"把对方棋子减到2枚，或让对方无路可走，即获胜。",
r6t:"⑥ 十二人莫拉巴拉",
r6c:"每方12枚棋子，并增加4条斜线。可以沿斜线移动，斜线三子连线也能成磨坊。",
r6c2:"操作：斜线移动也一样，先点击棋子，再点击目标点。",
r6c3:"放置阶段若棋盘全部占满，轮到行动的一方无路可走，判负。",
r7t:"7. 和棋",
r7c:"出现以下任一情况即自动和棋，没有提出和棋的按钮。",
r7c2:"・相同局面、相同行动方重复出现3次",
r7c3:"・连续50步（双方合计）没有形成磨坊",
r7c4:"・仅12子版：一方只剩3枚的状态下，连续10步（双方合计）无人取子",
r8t:"8. 详细规则",
r8c:"即使一步同时形成两个磨坊，也只能取走1枚棋子。",
r8c2:"9子版：可以拆开磨坊并在下一步立即重新合上；每次合上可取走1枚。",
r8c3:"12子版：拆开的磨坊不能在自己的下一步立即重做，需间隔一步。不成磨坊的放法可以。",
r8c4:"在线对战有三种速度：通常每步30秒，慢棋每步2分钟，信件对局每步24小时。慢棋和信件对局超时后会自动走一步。",
