myInq:"我的諮詢",
myInqPrep:"連線成功後，可在此查看自己送出的內容和回覆。",
r1t:"① 先放置棋子",
r1c:"點擊空點放置棋子。黑白雙方輪流放置，直到全部放完。黑方先行。",
r1c2:"操作：只需點擊白色箭頭所指的空點。",
r2t:"② 三子連線成「磨坊」",
r2c:"自己的3枚棋子在一條線上連成一線即成「磨坊」，可以取走對方1枚棋子。",
r2c2:"操作：連成磨坊後，點擊想要取走的對方棋子。",
r2c3:"磨坊內的棋子不能被取走；但若對方所有棋子都在磨坊內，則可從中取走。",
r3t:"③ 放完後移動棋子",
r3c:"全部放完後，沿線把棋子移到相鄰的空點。可移動的棋子會帶上與背景相襯的醒目顏色的圓環；點擊棋子後，可去的點會明顯發亮。",
r3c2:"操作：點擊想移動的棋子 → 再點擊發亮的相鄰點。",
r4t:"④ 只剩3枚時可以飛",
r4c:"當自己的棋子只剩3枚時，即使沒有連線，也可以飛到任意空點。",
r4c2:"操作：點擊自己的棋子 → 再點擊想飛往的空點。",
r5t:"⑤ 獲勝方法",
r5c:"把對方棋子減到2枚，或讓對方無路可走，即獲勝。",
r6t:"⑥ 十二人莫拉巴拉",
r6c:"每方12枚棋子，並增加4條斜線。可以沿斜線移動，斜線三子連線也能成磨坊。",
r6c2:"操作：斜線移動也一樣，先點擊棋子，再點擊目標點。",
r6c3:"放置階段若棋盤全部佔滿，輪到行動的一方無路可走，判負。",
r7t:"7. 和棋",
r7c:"出現以下任一情況即自動和棋，沒有提出和棋的按鈕。",
r7c2:"・相同局面、相同行動方重複出現3次",
r7c3:"・連續50步（雙方合計）沒有形成磨坊",
r7c4:"・僅12子版：一方只剩3枚的狀態下，連續10步（雙方合計）無人取子",
r8t:"8. 詳細規則",
r8c:"即使一步同時形成兩個磨坊，也只能取走1枚棋子。",
r8c2:"9子版：可以拆開磨坊並在下一步立即重新合上；每次合上可取走1枚。",
r8c3:"12子版：拆開的磨坊不能在自己的下一步立即重做，需間隔一步。不成磨坊的放法可以。",
r8c4:"線上對戰有三種速度：通常每步30秒，慢棋每步2分鐘，信件對局每步24小時。慢棋和信件對局逾時後會自動走一步。",
