r2c:"선 위에서 자기 말 세 개가 나란히 되면 '밀'이 되어 상대 말 하나를 가져갈 수 있습니다.",
r2c2:"조작: 세 개를 나란히 만든 뒤, 가져가고 싶은 상대 말을 누르세요.",
r2c3:"밀 안에 있는 말은 가져갈 수 없습니다. 단, 상대 말이 전부 밀 안에 있으면 그중에서 가져갈 수 있습니다.",
r3t:"③ 다 놓으면 움직이기",
r3c:"전부 놓은 뒤에는 선으로 이어진 옆 빈 점으로 말을 움직입니다. 움직일 수 있는 말에는 배경에 어울리는 눈에 띄는 색의 고리가 표시됩니다. 말을 누르면 갈 수 있는 점이 크게 빛납니다.",
r3c2:"조작: 움직이고 싶은 말을 누르기 → 빛나는 옆 점을 누르기.",
r4t:"④ 세 개가 되면 날기",
r4c:"자기 말이 세 개만 남으면, 선으로 이어져 있지 않아도 어느 빈 점으로든 날아갈 수 있습니다.",
r4c2:"조작: 자기 말을 누르기 → 날아가고 싶은 빈 점을 누르기.",
r5t:"⑤ 이기는 방법",
r5c:"상대 말을 두 개까지 줄이거나, 상대가 움직일 수 없게 하면 이깁니다.",
r6t:"⑥ 모라바라바(12개)",
r6c:"말은 각자 12개이고 대각선이 네 개 추가됩니다. 대각선으로도 움직일 수 있고, 대각선 세 개 나란히도 밀이 됩니다.",
r6c2:"조작: 대각선 이동도 말을 누른 뒤 목적지 점을 누릅니다.",
r6c3:"놓는 단계에서 보드가 전부 차면, 다음 차례인 사람이 움직일 수 없어 그 사람이 집니다.",
r7t:"7. 무승부",
r7c:"아래 중 하나가 되면 자동으로 무승부가 됩니다. 무승부를 제안하는 버튼은 없습니다.",
r7c2:"· 같은 보드·같은 차례가 세 번 반복됨",
r7c3:"· 밀이 되지 않는 수가 50수(양쪽 합계) 이어짐",
r7c4:"· 12개 버전만: 한쪽이 세 개인 상태에서 10수(양쪽 합계) 동안 아무도 가져가지 못함",
r8t:"8. 세부 규칙",
