r8c2:"9개 버전: 밀을 깨고 다음 수에 바로 다시 닫아도 됩니다. 닫을 때마다 하나를 가져갑니다.",
r8c3:"12개 버전: 깬 밀은 다음 자기 차례에 다시 만들 수 없습니다. 한 수 뒤에 다시 만들 수 있습니다. 밀이 되지 않는 두기는 가능합니다.",
r8c4:"온라인 대결의 속도는 3가지입니다. 보통은 한 수 30초, 느리게는 2분, 편지 대결은 24시간입니다. 느리게와 편지 대결은 시간이 끝나면 자동으로 한 수가 놓입니다.",
