contactPrep:"El destino de contacto aún no está listo. Cuando esté conectado, podrás enviar desde aquí. Por ahora los campos y el botón de envío están desactivados.",
myInq:"Tus mensajes",
myInqPrep:"Cuando el destino esté conectado, aquí podrás ver tus mensajes enviados y las respuestas.",
r1t:"① Primero coloca tus piezas",
r1c:"Toca un punto vacío para colocar una pieza. Negras y blancas se turnan hasta colocar todas las piezas. Las negras empiezan.",
r1c2:"Cómo jugar: solo toca el punto vacío hacia donde se mueve la flecha blanca.",
r2t:"② Tres en fila: un molino",
r2c:"Cuando tres de tus piezas forman una fila sobre una línea, eso es un molino y puedes retirar una pieza de tu rival.",
r2c2:"Cómo jugar: tras formar el molino, toca la pieza rival que quieres retirar.",
r2c3:"No se puede retirar una pieza que está en un molino, salvo que todas las piezas del rival estén en molinos; entonces sí puedes retirar una de un molino.",
r3t:"③ Después, mueve tus piezas",
r3c:"Cuando todas las piezas estén colocadas, desliza una pieza por una línea hasta un punto vacío vecino. Las piezas que pueden moverse llevan un anillo de un color que destaca sobre el fondo. Al tocar una pieza, sus destinos se iluminan.",
r3c2:"Cómo jugar: toca la pieza que quieres mover y luego un punto vecino iluminado.",
r4t:"④ ¿Solo te quedan tres? Puedes volar",
r4c:"Cuando te queden solo tres piezas, puedes volar a cualquier punto vacío, aunque no haya línea que los una.",
r4c2:"Cómo jugar: toca tu pieza y luego el punto vacío al que quieres volar.",
r5t:"⑤ Cómo se gana",
r5c:"Ganas si reduces a tu rival a dos piezas o si lo dejas sin ningún movimiento legal.",
r6t:"⑥ Morabaraba (12 piezas)",
r6c:"Cada jugador tiene 12 piezas y se añaden cuatro líneas diagonales. También puedes moverte en diagonal, y tres en fila en diagonal también forman un molino.",
r6c2:"Cómo jugar: los movimientos diagonales funcionan igual — toca la pieza y luego el punto de destino.",
r6c3:"Si el tablero se llena por completo durante la fase de colocación, el jugador al que le toca mover no puede mover y pierde.",
r7t:"7. Empates",
r7c:"La partida termina en empate automáticamente en cualquiera de los casos siguientes. No hay botón para ofrecer tablas.",
r7c2:"· La misma posición, con el mismo jugador al que le toca mover, se repite tres veces",
r7c3:"· Pasan 50 movimientos (entre ambos) sin que se forme un molino",
r7c4:"· Solo en la versión de 12: con un jugador reducido a tres piezas, pasan 10 movimientos (entre ambos) sin capturas",
r8t:"8. Detalles",
r8c:"Aunque un movimiento forme dos molinos a la vez, solo retiras una pieza.",
r8c2:"Versión de 9: puedes romper un molino y volver a cerrarlo en tu siguiente movimiento; cada vez que lo cierras, retiras una pieza.",
r8c3:"Versión de 12: un molino roto no puede rehacerse en tu siguiente movimiento; espera un movimiento. Los movimientos que no forman molino están permitidos.",
r8c4:"Las partidas en línea tienen tres ritmos: normal, 30 segundos por jugada; lento, 2 minutos; y por carta, 24 horas. En las partidas lentas y por carta, al acabarse el tiempo se juega una jugada automáticamente.",
