sendBtn:"Envoyer",
contactPrep:"La destination du formulaire n'est pas encore prête. Une fois connectée, vous pourrez envoyer depuis cette page. Pour le moment, les champs et le bouton d'envoi sont désactivés.",
myInq:"Vos messages",
myInqPrep:"Une fois la destination connectée, vous pourrez voir ici vos messages envoyés et les réponses.",
r1t:"① Placez d'abord vos pièces",
r1c:"Touchez un point libre pour placer une pièce. Les noirs et les blancs jouent à tour de rôle jusqu'à ce que toutes les pièces soient posées. Les noirs commencent.",
r1c2:"Comment jouer : touchez simplement le point libre vers lequel se déplace la flèche blanche.",
r2t:"② Trois alignées : un moulin",
r2c:"Quand trois de vos pièces sont alignées sur une ligne, c'est un moulin, et vous pouvez retirer une pièce adverse.",
r2c2:"Comment jouer : après avoir formé le moulin, touchez la pièce adverse que vous voulez retirer.",
r2c3:"Une pièce dans un moulin ne peut pas être prise, sauf si toutes les pièces adverses sont dans des moulins ; dans ce cas, vous pouvez en prendre une dans un moulin.",
r3t:"③ Ensuite, déplacez vos pièces",
r3c:"Quand toutes les pièces sont posées, faites glisser une pièce le long d'une ligne vers un point voisin libre. Les pièces déplaçables portent un anneau d'une couleur qui ressort sur le fond. Touchez une pièce et ses destinations s'illuminent.",
r3c2:"Comment jouer : touchez la pièce à déplacer, puis un point voisin illuminé.",
r4t:"④ Plus que trois pièces ? Vous pouvez voler",
r4c:"Quand il ne vous reste que trois pièces, vous pouvez voler vers n'importe quel point libre, même sans ligne entre les deux.",
r4c2:"Comment jouer : touchez votre pièce, puis le point libre où vous voulez voler.",
r5t:"⑤ Comment gagner",
r5c:"Vous gagnez en réduisant votre adversaire à deux pièces, ou en le laissant sans aucun coup possible.",
r6t:"⑥ Morabaraba (12 pièces)",
r6c:"Chaque joueur a 12 pièces et quatre lignes diagonales sont ajoutées. Vous pouvez aussi vous déplacer en diagonale, et trois pièces alignées en diagonale forment aussi un moulin.",
r6c2:"Comment jouer : les déplacements en diagonale fonctionnent de la même façon — touchez la pièce, puis le point d'arrivée.",
r6c3:"Si le plateau se remplit entièrement pendant la phase de placement, le joueur dont c'est le tour ne peut pas jouer et perd.",
r7t:"7. Parties nulles",
r7c:"La partie est automatiquement nulle dans l'un des cas ci-dessous. Il n'y a pas de bouton pour proposer la nulle.",
r7c2:"· La même position, avec le même joueur au trait, se répète trois fois",
r7c3:"· 50 coups (des deux joueurs) passent sans qu'un moulin soit formé",
r7c4:"· Version à 12 seulement : pendant qu'un joueur n'a que trois pièces, 10 coups (des deux joueurs) passent sans capture",
r8t:"8. Détails",
r8c:"Même si un coup forme deux moulins à la fois, vous ne retirez qu'une seule pièce.",
r8c2:"Version à 9 : vous pouvez casser un moulin et le refermer dès votre coup suivant ; à chaque fermeture, vous retirez une pièce.",
r8c3:"Version à 12 : un moulin cassé ne peut pas être refait à votre coup suivant ; attendez un coup. Les coups qui ne forment pas de moulin sont autorisés.",
r8c4:"En ligne, il y a trois rythmes : normal, 30 secondes par coup ; lent, 2 minutes ; et par correspondance, 24 heures. En lent et par correspondance, un coup est joué automatiquement quand le temps est écoulé.",
