sendBtn:"Senden",
contactPrep:"Das Kontaktziel ist noch nicht bereit. Sobald es verbunden ist, kannst du hier senden. Eingaben und der Senden-Button sind vorerst deaktiviert.",
myInq:"Deine Anfragen",
myInqPrep:"Sobald das Ziel verbunden ist, siehst du hier deine gesendeten Nachrichten und die Antworten.",
r1t:"① Zuerst die Steine setzen",
r1c:"Tippe auf einen freien Punkt, um einen Stein zu setzen. Schwarz und Weiß setzen abwechselnd, bis alle Steine auf dem Brett sind. Schwarz beginnt.",
r1c2:"So geht's: Tippe einfach auf den freien Punkt, auf den der weiße Pfeil zeigt.",
r2t:"② Drei in einer Reihe: eine Mühle",
r2c:"Wenn drei deiner Steine auf einer Linie stehen, ist das eine Mühle, und du darfst einen gegnerischen Stein wegnehmen.",
r2c2:"So geht's: Nachdem du die Mühle gebildet hast, tippe auf den gegnerischen Stein, den du wegnehmen willst.",
r2c3:"Ein Stein in einer Mühle kann nicht weggenommen werden – es sei denn, alle gegnerischen Steine stehen in Mühlen; dann darfst du einen aus einer Mühle nehmen.",
r3t:"③ Danach die Steine bewegen",
r3c:"Wenn alle Steine gesetzt sind, ziehe einen Stein entlang einer Linie auf einen benachbarten freien Punkt. Steine, die ziehen können, bekommen einen Ring in einer Farbe, die sich vom Hintergrund abhebt. Tippe einen Stein an, und seine Ziele leuchten auf.",
r3c2:"So geht's: Tippe den Stein an, den du bewegen willst, dann einen leuchtenden Nachbarpunkt.",
r4t:"④ Nur noch drei? Du darfst springen",
r4c:"Wenn du nur noch drei Steine hast, darfst du auf jeden freien Punkt springen, auch ohne Verbindungslinie.",
r4c2:"So geht's: Tippe deinen Stein an, dann den freien Punkt, zu dem du springen willst.",
r5t:"⑤ So gewinnst du",
r5c:"Du gewinnst, wenn du deinen Gegner auf zwei Steine reduzierst oder ihm keinen legalen Zug mehr lässt.",
r6t:"⑥ Morabaraba (12 Steine)",
r6c:"Jeder Spieler hat 12 Steine, und vier diagonale Linien kommen hinzu. Du kannst auch diagonal ziehen, und drei in einer Diagonalen bilden ebenfalls eine Mühle.",
r6c2:"So geht's: Diagonalzüge funktionieren gleich – Stein antippen, dann den Zielpunkt.",
r6c3:"Wenn das Brett in der Setzphase komplett voll wird, kann der Spieler am Zug nicht ziehen und verliert.",
r7t:"7. Unentschieden",
r7c:"In den folgenden Fällen endet die Partie automatisch unentschieden. Es gibt keinen Button, um ein Remis anzubieten.",
r7c2:"· Dieselbe Stellung mit demselben Spieler am Zug kommt dreimal vor",
r7c3:"· 50 Züge (beider Spieler zusammen) vergehen ohne Mühle",
r7c4:"· Nur bei 12 Steinen: Während ein Spieler nur drei Steine hat, vergehen 10 Züge (zusammen) ohne Schlagen",
r8t:"8. Details",
r8c:"Auch wenn ein Zug zwei Mühlen auf einmal bildet, nimmst du nur einen Stein weg.",
r8c2:"Version mit 9: Du darfst eine Mühle öffnen und gleich im nächsten Zug wieder schließen; bei jedem Schließen nimmst du einen Stein.",
r8c3:"Version mit 12: Eine geöffnete Mühle darfst du in deinem nächsten Zug nicht wieder schließen; warte einen Zug. Züge ohne Mühle sind erlaubt.",
r8c4:"Online gibt es drei Tempi: Normal 30 Sekunden pro Zug, Langsam 2 Minuten und Briefspiel 24 Stunden. Bei Langsam und Briefspiel wird ein Zug automatisch gespielt, wenn die Zeit abläuft.",
