sendBtn:"Enviar",
contactPrep:"O destino do contacto ainda não está pronto. Quando estiver ligado, poderás enviar a partir daqui. Por agora, os campos e o botão de envio estão desativados.",
myInq:"As tuas mensagens",
myInqPrep:"Quando o destino estiver ligado, poderás ver aqui as tuas mensagens enviadas e as respostas.",
r1t:"① Primeiro, coloca as peças",
r1c:"Toca num ponto vazio para colocar uma peça. Pretas e brancas alternam até todas as peças estarem no tabuleiro. As pretas começam.",
r1c2:"Como jogar: basta tocar no ponto vazio para onde a seta branca se move.",
r2t:"② Três em linha: um moinho",
r2c:"Quando três das tuas peças ficam alinhadas numa linha, isso é um moinho e podes retirar uma peça do adversário.",
r2c2:"Como jogar: depois de formares o moinho, toca na peça adversária que queres retirar.",
r2c3:"Uma peça dentro de um moinho não pode ser retirada, a menos que todas as peças do adversário estejam em moinhos; nesse caso, podes retirar uma de um moinho.",
r3t:"③ Depois, move as peças",
r3c:"Quando todas as peças estiverem colocadas, desliza uma peça ao longo de uma linha para um ponto vizinho vazio. As peças que se podem mover têm um anel de uma cor que se destaca do fundo. Toca numa peça e os destinos acendem.",
r3c2:"Como jogar: toca na peça que queres mover e depois num ponto vizinho aceso.",
r4t:"④ Só tens três? Podes voar",
r4c:"Quando só tiveres três peças, podes voar para qualquer ponto vazio, mesmo sem linha de ligação.",
r4c2:"Como jogar: toca na tua peça e depois no ponto vazio para onde queres voar.",
r5t:"⑤ Como ganhar",
r5c:"Ganhas ao reduzir o adversário a duas peças ou ao deixá-lo sem nenhuma jogada legal.",
r6t:"⑥ Morabaraba (12 peças)",
r6c:"Cada jogador tem 12 peças e são acrescentadas quatro linhas diagonais. Também te podes mover na diagonal, e três em linha na diagonal também formam um moinho.",
r6c2:"Como jogar: os movimentos diagonais funcionam da mesma forma — toca na peça e depois no ponto de destino.",
r6c3:"Se o tabuleiro ficar completamente cheio durante a fase de colocação, o jogador a quem cabe jogar não pode mover-se e perde.",
r7t:"7. Empates",
r7c:"O jogo termina empatado automaticamente em qualquer dos casos abaixo. Não há botão para oferecer empate.",
r7c2:"· A mesma posição, com o mesmo jogador a jogar, repete-se três vezes",
r7c3:"· Passam 50 jogadas (dos dois jogadores) sem se formar um moinho",
r7c4:"· Só na versão de 12: com um jogador reduzido a três peças, passam 10 jogadas (dos dois) sem capturas",
r8t:"8. Detalhes",
r8c:"Mesmo que uma jogada forme dois moinhos ao mesmo tempo, retiras apenas uma peça.",
r8c2:"Versão de 9: podes desfazer um moinho e voltar a fechá-lo logo na tua jogada seguinte; cada vez que o fechas, retiras uma peça.",
r8c3:"Versão de 12: um moinho desfeito não pode ser refeito na tua jogada seguinte; espera uma jogada. Jogadas que não formam moinho são permitidas.",
r8c4:"Os jogos online têm três ritmos: normal, 30 segundos por jogada; lento, 2 minutos; e por carta, 24 horas. Nos jogos lentos e por carta, quando o tempo acaba, uma jogada é feita automaticamente.",
