emailPh:"Solo se ti serve una risposta",
sendBtn:"Invia",
contactPrep:"La destinazione dei contatti non è ancora pronta. Quando sarà collegata, potrai inviare da qui. Per ora campi e pulsante di invio sono disattivati.",
myInq:"I tuoi messaggi",
myInqPrep:"Quando la destinazione sarà collegata, qui potrai vedere i tuoi messaggi inviati e le risposte.",
r1t:"① Prima posiziona i pezzi",
r1c:"Tocca un punto vuoto per posizionare un pezzo. Nero e Bianco si alternano finché tutti i pezzi sono sul tavoliere. Muove prima il Nero.",
r1c2:"Come si gioca: tocca semplicemente il punto vuoto verso cui si muove la freccia bianca.",
r2t:"② Tre in fila: un mulino",
r2c:"Quando tre dei tuoi pezzi sono in fila su una linea, è un mulino e puoi rimuovere un pezzo avversario.",
r2c2:"Come si gioca: dopo aver formato il mulino, tocca il pezzo avversario che vuoi rimuovere.",
r2c3:"Un pezzo dentro un mulino non può essere preso, a meno che tutti i pezzi avversari siano in mulini; in quel caso puoi prenderne uno da un mulino.",
r3t:"③ Poi muovi i pezzi",
r3c:"Quando tutti i pezzi sono posizionati, fai scorrere un pezzo lungo una linea fino a un punto vuoto vicino. I pezzi che possono muoversi hanno un anello di un colore che spicca sullo sfondo. Tocca un pezzo e le sue destinazioni si accendono.",
r3c2:"Come si gioca: tocca il pezzo da muovere, poi un punto vicino acceso.",
r4t:"④ Te ne restano tre? Puoi volare",
r4c:"Quando ti restano solo tre pezzi, puoi volare su qualsiasi punto vuoto, anche senza linea che li colleghi.",
r4c2:"Come si gioca: tocca il tuo pezzo, poi il punto vuoto dove vuoi volare.",
r5t:"⑤ Come si vince",
r5c:"Vinci riducendo l'avversario a due pezzi, oppure lasciandolo senza mosse legali.",
r6t:"⑥ Morabaraba (12 pezzi)",
r6c:"Ogni giocatore ha 12 pezzi e vengono aggiunte quattro linee diagonali. Puoi muoverti anche in diagonale, e tre in fila in diagonale formano anch'essi un mulino.",
r6c2:"Come si gioca: le mosse diagonali funzionano allo stesso modo — tocca il pezzo, poi il punto di arrivo.",
r6c3:"Se il tavoliere si riempie del tutto durante la fase di posizionamento, il giocatore di turno non può muovere e perde.",
r7t:"7. Patta",
r7c:"La partita è patta automaticamente in uno dei casi seguenti. Non c'è un pulsante per proporre la patta.",
r7c2:"· La stessa posizione, con lo stesso giocatore di turno, si ripete tre volte",
r7c3:"· Passano 50 mosse (di entrambi) senza che si formi un mulino",
r7c4:"· Solo versione a 12: mentre un giocatore ha tre pezzi, passano 10 mosse (di entrambi) senza catture",
r8t:"8. Dettagli",
r8c:"Anche se una mossa forma due mulini contemporaneamente, rimuovi comunque un solo pezzo.",
r8c2:"Versione a 9: puoi rompere un mulino e richiuderlo già alla mossa successiva; ogni volta che lo chiudi, rimuovi un pezzo.",
r8c3:"Versione a 12: un mulino rotto non può essere rifatto alla tua mossa successiva; aspetta una mossa. Le mosse che non formano un mulino sono consentite.",
r8c4:"Le partite online hanno tre ritmi: normale, 30 secondi a mossa; lento, 2 minuti; e per corrispondenza, 24 ore. Nelle partite lente e per corrispondenza, allo scadere del tempo viene giocata automaticamente una mossa.",
