sendBtn:"Versturen",
contactPrep:"De contactbestemming is nog niet klaar. Zodra die verbonden is, kun je hier versturen. De velden en de verstuurknop zijn voorlopig uitgeschakeld.",
myInq:"Jouw berichten",
myInqPrep:"Zodra de bestemming verbonden is, zie je hier je verzonden berichten en de antwoorden.",
r1t:"① Plaats eerst je stukken",
r1c:"Tik op een leeg punt om een stuk te plaatsen. Zwart en Wit plaatsen om de beurt, tot alle stukken op het bord staan. Zwart begint.",
r1c2:"Zo speel je: tik gewoon op het lege punt waar de witte pijl heen beweegt.",
r2t:"② Drie op een rij: een molen",
r2c:"Als drie van jouw stukken op een lijn staan, is dat een molen en mag je een stuk van je tegenstander weghalen.",
r2c2:"Zo speel je: tik na het vormen van de molen op het stuk van de tegenstander dat je wilt weghalen.",
r2c3:"Een stuk in een molen kan niet worden weggehaald, behalve als alle stukken van de tegenstander in molens staan; dan mag je er een uit een molen nemen.",
r3t:"③ Verplaats daarna je stukken",
r3c:"Als alle stukken geplaatst zijn, schuif je een stuk langs een lijn naar een naastgelegen leeg punt. Stukken die kunnen bewegen krijgen een ring in een kleur die opvalt tegen de achtergrond. Tik op een stuk en zijn doelen lichten op.",
r3c2:"Zo speel je: tik op het stuk dat je wilt verplaatsen, daarna op een oplichtend naastgelegen punt.",
r4t:"④ Nog maar drie over? Je mag vliegen",
r4c:"Als je nog maar drie stukken hebt, mag je naar elk leeg punt vliegen, ook zonder verbindingslijn.",
r4c2:"Zo speel je: tik op je stuk, daarna op het lege punt waar je heen wilt vliegen.",
r5t:"⑤ Zo win je",
r5c:"Je wint door je tegenstander tot twee stukken te verminderen, of door hem geen enkele legale zet te laten.",
r6t:"⑥ Morabaraba (12 stukken)",
r6c:"Elke speler heeft 12 stukken en er komen vier diagonale lijnen bij. Je kunt ook diagonaal bewegen, en drie op een rij diagonaal vormt ook een molen.",
r6c2:"Zo speel je: diagonale zetten werken hetzelfde — tik op het stuk, daarna op het doelpunt.",
r6c3:"Als het bord tijdens de plaatsingsfase helemaal vol raakt, kan de speler die aan zet is niet bewegen en verliest.",
r7t:"7. Remise",
r7c:"De partij eindigt automatisch in remise in een van de gevallen hieronder. Er is geen knop om remise aan te bieden.",
r7c2:"· Dezelfde stelling, met dezelfde speler aan zet, komt drie keer voor",
r7c3:"· Er gaan 50 zetten (van beide spelers samen) voorbij zonder molen",
r7c4:"· Alleen bij 12 stukken: terwijl een speler drie stukken heeft, gaan 10 zetten (samen) voorbij zonder slaan",
r8t:"8. Details",
r8c:"Ook als een zet twee molens tegelijk vormt, haal je maar één stuk weg.",
r8c2:"Versie met 9: je mag een molen openen en meteen in je volgende zet weer sluiten; elke keer dat je sluit, haal je een stuk weg.",
r8c3:"Versie met 12: een geopende molen mag je in je volgende zet niet opnieuw sluiten; wacht één zet. Zetten zonder molen zijn toegestaan.",
r8c4:"Online zijn er drie tempo's: normaal 30 seconden per zet, langzaam 2 minuten en correspondentie 24 uur. Bij langzaam en correspondentie wordt er automatisch een zet gespeeld als de tijd om is.",
