sendBtn:"Skicka",
contactPrep:"Kontaktmålet är inte redo än. När det är anslutet kan du skicka härifrån. Fälten och skicka-knappen är avstängda tills vidare.",
myInq:"Dina meddelanden",
myInqPrep:"När målet är anslutet kan du här se dina skickade meddelanden och svaren.",
r1t:"① Placera först dina pjäser",
r1c:"Tryck på en tom punkt för att placera en pjäs. Svart och Vit turas om tills alla pjäser är på brädet. Svart börjar.",
r1c2:"Så spelar du: tryck bara på den tomma punkt som den vita pilen rör sig mot.",
r2t:"② Tre i rad: en kvarn",
r2c:"När tre av dina pjäser står i rad på en linje är det en kvarn, och du får ta bort en av motståndarens pjäser.",
r2c2:"Så spelar du: efter att du bildat kvarnen trycker du på motståndarens pjäs som du vill ta bort.",
r2c3:"En pjäs i en kvarn kan inte tas, om inte alla motståndarens pjäser står i kvarnar; då får du ta en ur en kvarn.",
r3t:"③ Flytta sedan dina pjäser",
r3c:"När alla pjäser är placerade glider du en pjäs längs en linje till en angränsande tom punkt. Pjäser som kan flyttas får en ring i en färg som syns tydligt mot bakgrunden. Tryck på en pjäs så tänds dess mål.",
r3c2:"Så spelar du: tryck på pjäsen du vill flytta, sedan på en tänd grannpunkt.",
r4t:"④ Bara tre kvar? Du får flyga",
r4c:"När du bara har tre pjäser kvar får du flyga till vilken tom punkt som helst, även utan linje emellan.",
r4c2:"Så spelar du: tryck på din pjäs, sedan på den tomma punkt du vill flyga till.",
r5t:"⑤ Så vinner du",
r5c:"Du vinner genom att minska motståndaren till två pjäser, eller genom att lämna honom utan något lagligt drag.",
r6t:"⑥ Morabaraba (12 pjäser)",
r6c:"Varje spelare har 12 pjäser och fyra diagonala linjer läggs till. Du kan också flytta diagonalt, och tre i rad diagonalt bildar också en kvarn.",
r6c2:"Så spelar du: diagonalflytt fungerar likadant — tryck på pjäsen, sedan på målpunkten.",
r6c3:"Om brädet blir helt fullt under placeringsfasen kan spelaren som ska flytta inte röra sig och förlorar.",
r7t:"7. Remi",
r7c:"Partiet blir automatiskt remi i något av fallen nedan. Det finns ingen knapp för att erbjuda remi.",
r7c2:"· Samma ställning, med samma spelare vid draget, upprepas tre gånger",
r7c3:"· 50 drag (båda spelarna tillsammans) går utan att en kvarn bildas",
r7c4:"· Endast 12-versionen: medan en spelare har tre pjäser går 10 drag (tillsammans) utan att någon slår",
r8t:"8. Detaljer",
r8c:"Även om ett drag bildar två kvarnar samtidigt tar du bara bort en pjäs.",
r8c2:"9-versionen: du får bryta en kvarn och stänga den igen redan i ditt nästa drag; varje gång du stänger den tar du en pjäs.",
r8c3:"12-versionen: en bruten kvarn får inte göras om i ditt nästa drag; vänta ett drag. Drag som inte bildar en kvarn är tillåtna.",
r8c4:"Online finns tre tempon: normalt 30 sekunder per drag, långsamt 2 minuter och brevspel 24 timmar. I långsamma spel och brevspel spelas ett drag automatiskt när tiden tar slut.",
