r3c2:"Jak grać: dotknij pionka, który chcesz ruszyć, a potem podświetlonego sąsiedniego punktu.",
r4t:"④ Zostały ci trzy? Możesz latać",
r4c:"Gdy zostaną ci tylko trzy pionki, możesz przelatywać na dowolny pusty punkt, nawet bez linii łączącej.",
r4c2:"Jak grać: dotknij swojego pionka, a potem pustego punktu, na który chcesz polecieć.",
r5t:"⑤ Jak wygrać",
r5c:"Wygrywasz, zmniejszając liczbę pionków przeciwnika do dwóch albo zostawiając go bez żadnego legalnego ruchu.",
r6t:"⑥ Morabaraba (12 pionków)",
r6c:"Każdy gracz ma 12 pionków i dochodzą cztery linie ukośne. Można poruszać się także po przekątnej, a trzy w rzędzie po przekątnej też tworzą młynek.",
r6c2:"Jak grać: ruchy po przekątnej działają tak samo — dotknij pionka, a potem punktu docelowego.",
r6c3:"Jeśli w fazie ustawiania plansza zapełni się całkowicie, gracz, którego jest kolej, nie może się ruszyć i przegrywa.",
r7t:"7. Remis",
r7c:"Gra kończy się remisem automatycznie w każdym z poniższych przypadków. Nie ma przycisku proponowania remisu.",
r7c2:"· Ta sama pozycja, z tym samym graczem na ruchu, powtarza się trzy razy",
r7c3:"· Mija 50 ruchów (obu graczy łącznie) bez utworzenia młynka",
r7c4:"· Tylko wersja 12: gdy gracz ma trzy pionki, mija 10 ruchów (łącznie) bez zbicia",
r8t:"8. Szczegóły",
r8c:"Nawet jeśli jeden ruch utworzy dwa młynki naraz, zdejmujesz tylko jeden pionek.",
r8c2:"Wersja 9: możesz rozbić młynek i od razu zamknąć go w następnym ruchu; za każdym zamknięciem zdejmujesz jeden pionek.",
r8c3:"Wersja 12: rozbitego młynka nie wolno odtworzyć w swoim następnym ruchu; odczekaj jeden ruch. Ruchy, które nie tworzą młynka, są dozwolone.",
r8c4:"W grze online są trzy tempa: normalne 30 sekund na ruch, powolne 2 minuty i korespondencyjne 24 godziny. W grach powolnych i korespondencyjnych ruch jest wykonywany automatycznie po upływie czasu.",
