emailPh:"Jen pokud potřebuješ odpověď",
sendBtn:"Odeslat",
contactPrep:"Cíl kontaktu ještě není připravený. Až bude připojený, budeš moct odesílat odtud. Pole a tlačítko odeslání jsou zatím vypnuté.",
myInq:"Tvé zprávy",
myInqPrep:"Až bude cíl připojený, uvidíš tu své odeslané zprávy a odpovědi.",
r1t:"① Nejprve pokládej kameny",
r1c:"Klepni na volný bod a polož kámen. Černý a bílý se střídají, dokud nejsou všechny kameny na desce. Začíná černý.",
r1c2:"Jak hrát: stačí klepnout na volný bod, ke kterému míří bílá šipka.",
r2t:"② Tři v řadě: mlýnek",
r2c:"Když tři tvé kameny stojí v řadě na čáře, je to mlýnek a smíš odebrat jeden soupeřův kámen.",
r2c2:"Jak hrát: po vytvoření mlýnku klepni na soupeřův kámen, který chceš odebrat.",
r2c3:"Kámen v mlýnku nelze odebrat, ledaže jsou všechny soupeřovy kameny v mlýncích; pak smíš odebrat jeden z mlýnku.",
r3t:"③ Pak kameny posouvej",
r3c:"Když jsou všechny kameny položené, posuň kámen po čáře na sousední volný bod. Kameny, které se mohou hýbat, mají kroužek v barvě, která vynikne na pozadí. Klepni na kámen a jeho cíle se rozsvítí.",
r3c2:"Jak hrát: klepni na kámen, který chceš posunout, a pak na rozsvícený sousední bod.",
r4t:"④ Zbývají ti tři? Můžeš létat",
r4c:"Když ti zbývají jen tři kameny, smíš letět na libovolný volný bod, i bez spojovací čáry.",
r4c2:"Jak hrát: klepni na svůj kámen a pak na volný bod, kam chceš letět.",
r5t:"⑤ Jak vyhrát",
r5c:"Vyhraješ, když soupeře snížíš na dva kameny, nebo když mu nenecháš žádný legální tah.",
r6t:"⑥ Morabaraba (12 kamenů)",
r6c:"Každý hráč má 12 kamenů a přibývají čtyři úhlopříčné čáry. Můžeš se pohybovat i po úhlopříčce a tři v řadě po úhlopříčce také tvoří mlýnek.",
r6c2:"Jak hrát: úhlopříčné tahy fungují stejně — klepni na kámen a pak na cílový bod.",
r6c3:"Pokud se deska během pokládání úplně zaplní, hráč na tahu se nemůže pohnout a prohrává.",
r7t:"7. Remíza",
r7c:"Partie končí remízou automaticky v některém z níže uvedených případů. Tlačítko pro nabídnutí remízy tu není.",
r7c2:"· Stejná pozice se stejným hráčem na tahu se opakuje třikrát",
r7c3:"· Uplyne 50 tahů (obou hráčů dohromady), aniž by vznikl mlýnek",
r7c4:"· Jen verze 12: zatímco má hráč tři kameny, uplyne 10 tahů (dohromady), aniž by někdo bral",
r8t:"8. Podrobnosti",
r8c:"I když jeden tah vytvoří dva mlýnky najednou, odebíráš jen jeden kámen.",
r8c2:"Verze 9: mlýnek smíš rozbít a hned v dalším tahu zase zavřít; při každém zavření odebereš jeden kámen.",
r8c3:"Verze 12: rozbitý mlýnek nesmíš ve svém dalším tahu znovu udělat; počkej jeden tah. Tahy, které mlýnek netvoří, jsou dovolené.",
r8c4:"Online jsou tři tempa: normální 30 sekund na tah, pomalé 2 minuty a korespondenční 24 hodin. V pomalých a korespondenčních hrách se po vypršení času tah zahraje automaticky.",
