sendBtn:"Отправить",
contactPrep:"Адрес для обращений ещё не готов. Когда он подключится, здесь можно будет отправлять сообщения. Пока поля и кнопка отправки отключены.",
myInq:"Ваши обращения",
myInqPrep:"Когда адрес подключится, здесь можно будет видеть свои отправленные сообщения и ответы на них.",
r1t:"① Сначала расставьте фишки",
r1c:"Нажмите на свободную точку, чтобы поставить фишку. Чёрные и белые ходят по очереди, пока все фишки не окажутся на доске. Первыми ходят чёрные.",
r1c2:"Как играть: просто нажмите на свободную точку, к которой движется белая стрелка.",
r2t:"② Три в ряд — мельница",
r2c:"Когда три ваши фишки выстраиваются в ряд на линии, это мельница, и вы можете снять одну фишку соперника.",
r2c2:"Как играть: построив мельницу, нажмите на фишку соперника, которую хотите снять.",
r2c3:"Фишку, стоящую в мельнице, снять нельзя — кроме случая, когда все фишки соперника стоят в мельницах; тогда можно снять одну из мельницы.",
r3t:"③ Затем двигайте фишки",
r3c:"Когда все фишки расставлены, сдвигайте фишку по линии на соседнюю свободную точку. Фишки, которые могут ходить, получают кольцо цвета, который хорошо выделяется на фоне. Нажмите на фишку — её цели подсветятся.",
r3c2:"Как играть: нажмите на фишку, которую хотите сдвинуть, затем на подсвеченную соседнюю точку.",
r4t:"④ Осталось три? Можно летать",
r4c:"Когда у вас останется только три фишки, вы можете перелетать на любую свободную точку, даже без соединяющей линии.",
r4c2:"Как играть: нажмите на свою фишку, затем на свободную точку, куда хотите перелететь.",
r5t:"⑤ Как выиграть",
r5c:"Вы выигрываете, сократив соперника до двух фишек или оставив его без единого легального хода.",
r6t:"⑥ Морабараба (12 фишек)",
r6c:"У каждого игрока по 12 фишек, и добавляются четыре диагональные линии. Можно ходить и по диагонали, а три в ряд по диагонали тоже образуют мельницу.",
r6c2:"Как играть: ходы по диагонали работают так же — нажмите на фишку, затем на точку назначения.",
r6c3:"Если во время расстановки доска заполнится полностью, игрок, чья очередь ходить, не может походить и проигрывает.",
r7t:"7. Ничья",
r7c:"Партия автоматически заканчивается вничью в любом из случаев ниже. Кнопки предложить ничью нет.",
r7c2:"· Одна и та же позиция при том же игроке на ходу повторяется три раза",
r7c3:"· Проходит 50 ходов (обоих игроков вместе) без образования мельницы",
r7c4:"· Только в версии на 12: пока у игрока три фишки, проходит 10 ходов (вместе) без взятий",
r8t:"8. Подробности",
r8c:"Даже если один ход образует сразу две мельницы, вы снимаете только одну фишку.",
r8c2:"Версия на 9: мельницу можно разрушить и тут же закрыть на своём следующем ходу; при каждом закрытии вы снимаете одну фишку.",
r8c3:"Версия на 12: разрушенную мельницу нельзя восстановить на своём следующем ходу; подождите один ход. Ходы, не образующие мельницу, разрешены.",
r8c4:"В онлайне три темпа: обычный — 30 секунд на ход, медленный — 2 минуты, по переписке — 24 часа. В медленной игре и по переписке ход делается автоматически, когда время истекает.",
