emailPh:"Chỉ nhập khi cần trả lời",
sendBtn:"Gửi",
contactPrep:"Địa chỉ nhận liên hệ chưa sẵn sàng. Khi được kết nối, bạn sẽ gửi được từ đây. Hiện các ô nhập và nút gửi đang bị tắt.",
myInq:"Tin nhắn của tôi",
myInqPrep:"Khi địa chỉ được kết nối, bạn sẽ xem được tại đây các tin đã gửi và câu trả lời.",
r1t:"① Đặt quân trước",
r1c:"Chạm vào điểm trống để đặt quân. Đen và Trắng thay phiên nhau đặt cho đến khi mọi quân đều lên bàn. Đen đi trước.",
r1c2:"Cách chơi: chỉ cần chạm vào điểm trống mà mũi tên trắng đang hướng tới.",
r2t:"② Ba quân thẳng hàng: cối xay",
r2c:"Khi ba quân của bạn thẳng hàng trên một đường, đó là cối xay, và bạn được lấy một quân của đối thủ.",
r2c2:"Cách chơi: sau khi tạo cối xay, chạm vào quân đối thủ bạn muốn lấy.",
r2c3:"Quân nằm trong cối xay không thể bị lấy, trừ khi mọi quân của đối thủ đều nằm trong cối xay; khi đó bạn có thể lấy một quân trong cối xay.",
r3t:"③ Rồi di chuyển quân",
r3c:"Khi mọi quân đã được đặt, trượt quân dọc theo đường tới điểm trống kề bên. Quân có thể di chuyển sẽ có vòng màu nổi bật trên nền. Chạm vào quân và các đích sẽ sáng lên.",
r3c2:"Cách chơi: chạm quân muốn di chuyển, rồi chạm điểm kề bên đang sáng.",
r4t:"④ Chỉ còn ba quân? Bạn có thể bay",
r4c:"Khi chỉ còn ba quân, bạn có thể bay tới bất kỳ điểm trống nào, dù không có đường nối.",
r4c2:"Cách chơi: chạm quân của bạn, rồi chạm điểm trống muốn bay tới.",
r5t:"⑤ Cách thắng",
r5c:"Bạn thắng khi giảm đối thủ xuống còn hai quân, hoặc khiến đối thủ không còn nước đi hợp lệ.",
r6t:"⑥ Morabaraba (12 quân)",
r6c:"Mỗi người có 12 quân và thêm bốn đường chéo. Bạn cũng có thể đi chéo, và ba quân thẳng hàng theo đường chéo cũng tạo thành cối xay.",
r6c2:"Cách chơi: đi chéo cũng giống vậy — chạm quân, rồi chạm điểm đích.",
r6c3:"Nếu bàn cờ đầy hoàn toàn trong giai đoạn đặt quân, người tới lượt sẽ không di chuyển được và thua.",
r7t:"7. Hòa",
r7c:"Ván cờ tự động hòa trong bất kỳ trường hợp nào dưới đây. Không có nút xin hòa.",
r7c2:"· Cùng một thế cờ, với cùng người tới lượt, lặp lại ba lần",
r7c3:"· 50 nước đi (cả hai người cộng lại) trôi qua mà không tạo cối xay",
r7c4:"· Chỉ bản 12 quân: khi một người còn ba quân, 10 nước đi (cộng lại) trôi qua mà không ai lấy quân",
r8t:"8. Chi tiết",
r8c:"Dù một nước đi tạo hai cối xay cùng lúc, bạn vẫn chỉ lấy một quân.",
r8c2:"Bản 9 quân: bạn có thể phá cối xay và đóng lại ngay ở nước tiếp theo của mình; mỗi lần đóng, bạn lấy một quân.",
r8c3:"Bản 12 quân: cối xay đã phá không được làm lại ở nước tiếp theo của bạn; hãy chờ một nước. Các nước không tạo cối xay vẫn được phép.",
r8c4:"Ván trực tuyến có ba nhịp: thường 30 giây mỗi nước, chậm 2 phút, và qua thư 24 giờ. Ở ván chậm và qua thư, hết giờ một nước sẽ được đi tự động.",
