contactPrep:"ช่องทางติดต่อยังไม่พร้อม เมื่อเชื่อมต่อได้แล้วจะส่งจากตรงนี้ได้ ตอนนี้ช่องกรอกและปุ่มส่งถูกปิดไว้",
