myInqPrep:"เมื่อช่องทางเชื่อมต่อแล้ว คุณจะเห็นข้อความที่ส่งไปและคำตอบได้ที่ตรงนี้",
r1t:"① วางหมากก่อน",
r1c:"แตะจุดที่ว่างเพื่อวางหมาก ดำกับขาวสลับกันวางจนวางหมากครบทุกตัว ดำเริ่มก่อน",
r1c2:"วิธีเล่น: แตะจุดว่างที่ลูกศรสีขาวเลื่อนไปหาเท่านั้น",
r2t:"② เรียงสามตัวเป็นแถว: มิลล์",
r2c:"เมื่อหมากของคุณสามตัวเรียงกันบนเส้น จะเรียกว่า มิลล์ และคุณหยิบหมากของคู่แข่งออกได้หนึ่งตัว",
r2c2:"วิธีเล่น: หลังจากเรียงเป็นมิลล์แล้ว แตะหมากคู่แข่งที่ต้องการหยิบออก",
r2c3:"หมากที่อยู่ในมิลล์จะถูกหยิบออกไม่ได้ เว้นแต่หมากของคู่แข่งทุกตัวอยู่ในมิลล์ จึงหยิบจากในมิลล์ได้",
r3t:"③ จากนั้นเลื่อนหมาก",
r3c:"เมื่อวางหมากครบแล้ว เลื่อนหมากไปตามเส้นยังจุดว่างข้าง ๆ หมากที่เลื่อนได้จะมีวงแหวนสีที่โดดเด่นเข้ากับพื้นหลัง แตะหมากแล้วจุดหมายจะสว่างขึ้น",
r3c2:"วิธีเล่น: แตะหมากที่อยากเลื่อน แล้วแตะจุดข้าง ๆ ที่สว่าง",
r4t:"④ เหลือสามตัว? บินได้",
r4c:"เมื่อหมากของคุณเหลือเพียงสามตัว คุณสามารถบินไปยังจุดว่างใดก็ได้ แม้ไม่มีเส้นเชื่อม",
r4c2:"วิธีเล่น: แตะหมากของคุณ แล้วแตะจุดว่างที่อยากบินไป",
r5t:"⑤ วิธีชนะ",
r5c:"คุณจะชนะเมื่อลดหมากของคู่แข่งเหลือสองตัว หรือทำให้คู่แข่งไม่มีตาเดินที่ถูกต้อง",
r6t:"⑥ โมราบาราบา (12 ตัว)",
r6c:"ผู้เล่นแต่ละคนมีหมาก 12 ตัว และมีเส้นทแยงเพิ่มสี่เส้น เดินทแยงได้เช่นกัน และเรียงสามตัวตามแนวทแยงก็เป็นมิลล์ด้วย",
r6c2:"วิธีเล่น: การเดินทแยงทำแบบเดียวกัน — แตะหมาก แล้วแตะจุดหมาย",
r6c3:"หากกระดานเต็มทั้งหมดในช่วงวางหมาก ผู้เล่นที่ถึงตาเดินจะเดินไม่ได้และแพ้",
r7t:"7. เสมอ",
r7c:"เกมจะเสมอโดยอัตโนมัติในกรณีใดกรณีหนึ่งต่อไปนี้ ไม่มีปุ่มเสนอเสมอ",
r7c2:"· หน้ากระดานเดิม ผู้เล่นตาเดิม เกิดซ้ำสามครั้ง",
r7c3:"· เดินครบ 50 ตา (รวมสองฝ่าย) โดยไม่เกิดมิลล์",
r7c4:"· เฉพาะแบบ 12 ตัว: ขณะที่ฝ่ายหนึ่งมีหมากสามตัว เดินครบ 10 ตา (รวมกัน) โดยไม่มีใครหยิบหมากได้",
r8t:"8. รายละเอียด",
r8c:"แม้เดินครั้งเดียวเกิดมิลล์สองแห่งพร้อมกัน ก็หยิบออกได้เพียงหนึ่งตัว",
r8c2:"แบบ 9 ตัว: เปิดมิลล์แล้วปิดกลับในตาถัดไปของตัวเองทันทีได้ ทุกครั้งที่ปิดจะหยิบได้หนึ่งตัว",
r8c3:"แบบ 12 ตัว: มิลล์ที่เปิดแล้วห้ามทำซ้ำในตาถัดไปของตัวเอง ต้องรอหนึ่งตา ส่วนการเดินที่ไม่เป็นมิลล์ทำได้",
r8c4:"ออนไลน์มี 3 จังหวะ: ปกติ 30 วินาทีต่อตา, ช้า 2 นาที และจดหมาย 24 ชั่วโมง ในเกมแบบช้าและแบบจดหมาย เมื่อหมดเวลา ระบบจะเดินให้อัตโนมัติหนึ่งตา",
