emailPh:"केवल तब लिखें जब जवाब चाहिए",
sendBtn:"भेजें",
contactPrep:"संपर्क का पता अभी तैयार नहीं है। जब यह जुड़ जाएगा, तब आप यहाँ से भेज सकेंगे। फिलहाल इनपुट और भेजने का बटन बंद हैं।",
myInq:"मेरे संदेश",
myInqPrep:"जब पता जुड़ जाएगा, तब आप यहाँ अपने भेजे संदेश और जवाब देख सकेंगे।",
r1t:"① पहले मोहरे रखें",
r1c:"मोहरा रखने के लिए खाली बिंदु पर टैप करें। काला और सफेद बारी-बारी से रखते हैं जब तक सारे मोहरे बोर्ड पर न आ जाएँ। काला पहले चलता है।",
r1c2:"कैसे खेलें: बस उस खाली बिंदु पर टैप करें जिस ओर सफेद तीर जा रहा है।",
r2t:"② तीन एक कतार में: मिल",
r2c:"जब आपके तीन मोहरे किसी रेखा पर एक कतार में आ जाते हैं, वह मिल होती है और आप प्रतिद्वंद्वी का एक मोहरा हटा सकते हैं।",
r2c2:"कैसे खेलें: मिल बनाने के बाद, प्रतिद्वंद्वी के जिस मोहरे को हटाना है उस पर टैप करें।",
r2c3:"मिल के अंदर का मोहरा नहीं हटाया जा सकता, सिवाय तब जब प्रतिद्वंद्वी के सारे मोहरे मिलों में हों; तब आप मिल के अंदर से एक हटा सकते हैं।",
r3t:"③ फिर मोहरे चलाएँ",
r3c:"सारे मोहरे रखे जाने के बाद, मोहरे को रेखा के साथ-साथ बगल के खाली बिंदु तक खिसकाएँ। जो मोहरे चल सकते हैं, उन्हें पृष्ठभूमि पर साफ़ दिखने वाले रंग का छल्ला मिलता है। मोहरे पर टैप करें तो उसके गंतव्य जगमगा उठते हैं।",
r3c2:"कैसे खेलें: जिस मोहरे को चलाना है उस पर टैप करें, फिर जगमगाते बगल वाले बिंदु पर टैप करें।",
r4t:"④ सिर्फ तीन बचे? आप उड़ सकते हैं",
r4c:"जब आपके सिर्फ तीन मोहरे बचें, तो आप किसी भी खाली बिंदु पर उड़ सकते हैं, चाहे जोड़ने वाली रेखा न हो।",
r4c2:"कैसे खेलें: अपने मोहरे पर टैप करें, फिर उस खाली बिंदु पर टैप करें जहाँ उड़कर जाना है।",
r5t:"⑤ जीत कैसे मिलती है",
r5c:"आप प्रतिद्वंद्वी को दो मोहरों तक घटाकर, या उसे कोई वैध चाल न छोड़कर जीतते हैं।",
r6t:"⑥ मोराबराबा (12 मोहरे)",
r6c:"हर खिलाड़ी के पास 12 मोहरे होते हैं और चार तिरछी रेखाएँ जुड़ जाती हैं। आप तिरछे भी चल सकते हैं, और तिरछे तीन एक कतार में भी मिल बनती है।",
r6c2:"कैसे खेलें: तिरछी चालें भी वैसे ही चलती हैं — मोहरे पर टैप करें, फिर गंतव्य बिंदु पर।",
r6c3:"अगर रखने के चरण में बोर्ड पूरी तरह भर जाए, तो जिस खिलाड़ी की बारी है वह चल नहीं सकता और हार जाता है।",
r7t:"7. ड्रॉ",
r7c:"नीचे दिए किसी भी मामले में खेल अपने आप ड्रॉ हो जाता है। ड्रॉ पेश करने का कोई बटन नहीं है।",
r7c2:"· वही स्थिति, उसी खिलाड़ी की बारी के साथ, तीन बार दोहराई जाती है",
r7c3:"· मिल बने बिना 50 चालें (दोनों खिलाड़ियों की मिलाकर) बीत जाती हैं",
r7c4:"· केवल 12 वाले संस्करण में: जब किसी खिलाड़ी के तीन मोहरे हों, तब बिना किसी के मोहरा हटाए 10 चालें (मिलाकर) बीत जाती हैं",
r8t:"8. बारीकियाँ",
r8c:"भले ही एक चाल से एक साथ दो मिल बन जाएँ, आप सिर्फ एक ही मोहरा हटाते हैं।",
r8c2:"9 वाला संस्करण: आप मिल तोड़कर अपनी अगली ही चाल में उसे फिर बंद कर सकते हैं; हर बार बंद करने पर आप एक मोहरा हटाते हैं।",
r8c3:"12 वाला संस्करण: तोड़ी हुई मिल अपनी अगली चाल में दोबारा नहीं बनाई जा सकती; एक चाल रुकें। जो चालें मिल नहीं बनातीं, वे चल सकती हैं।",
r8c4:"ऑनलाइन खेल की तीन गति हैं: सामान्य हर चाल 30 सेकंड, धीमा 2 मिनट, और पत्र-खेल 24 घंटे। धीमे और पत्र-खेल में समय खत्म होने पर एक चाल अपने आप चल जाती है।",
