myInqPrep:"عندما تتصل الوجهة، ستتمكن هنا من رؤية رسائلك المرسلة والردود عليها.",
r1t:"① ضع القطع أولًا",
r1c:"انقر نقطة فارغة لوضع قطعة. يتناوب الأسود والأبيض على الوضع حتى توضع كل القطع على اللوحة. الأسود يبدأ.",
r1c2:"طريقة اللعب: انقر فقط النقطة الفارغة التي يتجه إليها السهم الأبيض.",
r2t:"② ثلاثة في صف واحد: طاحونة",
r2c:"عندما تصطف ثلاث من قطعك على خط واحد فهذه طاحونة، ويمكنك إزالة قطعة واحدة من قطع الخصم.",
r2c2:"طريقة اللعب: بعد تكوين الطاحونة، انقر قطعة الخصم التي تريد إزالتها.",
r2c3:"لا يمكن أخذ قطعة داخل طاحونة، إلا إذا كانت كل قطع الخصم داخل طواحين؛ عندها يمكنك أخذ واحدة من داخل طاحونة.",
r3t:"③ ثم حرّك القطع",
r3c:"بعد وضع كل القطع، حرّك قطعة على طول خط إلى نقطة فارغة مجاورة. القطع القابلة للحركة تحصل على حلقة بلون بارز يناسب الخلفية. انقر قطعة فتضيء وجهاتها.",
r3c2:"طريقة اللعب: انقر القطعة التي تريد تحريكها، ثم انقر نقطة مجاورة مضيئة.",
r4t:"④ بقي لك ثلاث؟ يمكنك الطيران",
r4c:"عندما لا يتبقى لك سوى ثلاث قطع، يمكنك الطيران إلى أي نقطة فارغة، حتى بدون خط يربط بينهما.",
r4c2:"طريقة اللعب: انقر قطعتك، ثم انقر النقطة الفارغة التي تريد الطيران إليها.",
r5t:"⑤ كيفية الفوز",
r5c:"تفوز بتقليص قطع الخصم إلى قطعتين، أو بتركه دون أي حركة قانونية.",
r6t:"⑥ مورابارابا (12 قطعة)",
r6c:"لكل لاعب 12 قطعة وتُضاف أربعة خطوط قطرية. يمكنك التحرك قطريًا أيضًا، وثلاث قطع في صف قطري تكوّن طاحونة أيضًا.",
r6c2:"طريقة اللعب: الحركات القطرية تعمل بنفس الطريقة — انقر القطعة، ثم نقطة الوصول.",
r6c3:"إذا امتلأت اللوحة تمامًا أثناء مرحلة الوضع، فلن يتمكن اللاعب صاحب الدور من التحرك ويخسر.",
r7t:"7. التعادل",
r7c:"تنتهي المباراة بالتعادل تلقائيًا في أي من الحالات التالية. لا يوجد زر لعرض التعادل.",
r7c2:"· تتكرر نفس الوضعية مع نفس اللاعب صاحب الدور ثلاث مرات",
r7c3:"· تمر 50 حركة (لكلا اللاعبين معًا) دون تكوين طاحونة",
r7c4:"· نسخة 12 فقط: بينما يمتلك أحد اللاعبين ثلاث قطع، تمر 10 حركات (معًا) دون أن يأخذ أحد أي قطعة",
r8t:"8. تفاصيل",
r8c:"حتى لو كوّنت حركة واحدة طاحونتين في وقت واحد، فإنك تزيل قطعة واحدة فقط.",
r8c2:"نسخة 9: يمكنك كسر طاحونة وإعادة إغلاقها في حركتك التالية مباشرة؛ وفي كل مرة تغلقها تزيل قطعة.",
r8c3:"نسخة 12: لا يجوز إعادة تكوين طاحونة مكسورة في حركتك التالية؛ انتظر حركة واحدة. الحركات التي لا تكوّن طاحونة مسموحة.",
r8c4:"للعب عبر الإنترنت ثلاث سرعات: العادي 30 ثانية لكل نقلة، والبطيء دقيقتان، والمراسلة 24 ساعة. في الألعاب البطيئة وألعاب المراسلة تُلعب نقلة تلقائيًا عند انتهاء الوقت.",
